import sys

def unique_obst_brute(grid, m, n):
    def dfs(i, j):
        if i == m - 1 and j == n - 1:
            return 1 if grid[i][j] == 0 else 0
        if i >= m or j >= n or grid[i][j] == 1:
            return 0
        return dfs(i + 1, j) + dfs(i, j + 1)
    if grid[0][0] == 1 or grid[m - 1][n - 1] == 1:
        return 0
    return dfs(0, 0)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    grid = []
    idx = 2
    for _ in range(m):
        grid.append([int(x) for x in data[idx:idx + n]])
        idx += n
    print(unique_obst_brute(grid, m, n))

import sys

def unique_obst_opt(grid, m, n):
    if not m or not n or grid[0][0] == 1:
        return 0
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
                continue
            if i == 0 and j == 0:
                continue
            top = dp[i - 1][j] if i > 0 else 0
            left = dp[i][j - 1] if j > 0 else 0
            dp[i][j] = top + left
    return dp[m - 1][n - 1]

