import sys

def unique_obst_best(grid, m, n):
    if not m or not n or grid[0][0] == 1:
        return 0
    dp = [0] * n
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[j] = 0
                continue
            if i == 0 and j == 0:
                dp[0] = 1
            elif i == 0:
                dp[j] = dp[j - 1]
            elif j == 0:
                dp[0] = dp[0]
            else:
                dp[j] = dp[j] + dp[j - 1]
    return dp[n - 1]

